; Colour RAM fill
; $6e7b-$6e9b

; Sets colour RAM row 0 ($d800-$d827) to 9, then fills $d800+Y to $dbff with A. Input: A = colour, Y = first offset. Output: colour_ram_ptr = $dc00, Y = 0.
fill_colour_ram
        pha
        ldx #$27
        lda #$09
fill_colour_ram_row0
        sta $d800,x                     ; Row 0 gets colour 9 (multicolour, colour 1).
        dex
        bpl fill_colour_ram_row0
        ldx #$00
        stx text_ptr
        ldx #$d8
        stx text_ptr_hi
        ldx #$03
        pla
fill_colour_ram_loop
        sta (text_ptr),y                ; Fills four pages, $d8-$db.
        iny
        bne fill_colour_ram_loop
        inc text_ptr_hi
        dex
        bpl fill_colour_ram_loop
        rts
